import * as Sentry from '@sentry/nuxt';

const {
  sentry: { dsn },
  environment,
  sentryRelease,
} = useRuntimeConfig().public;

if (dsn)
  Sentry.init({
    dsn: dsn,
    tunnel: '/api/sentry',
    beforeSend(event, hint) {
      // console.log('Sentry event:', event);
      if (hint.originalException instanceof Error && hint.originalException.name === 'OfflineMutationError') {
        return null;
      }
      const statusCode = event.contexts?.response?.status_code;
      if (
        statusCode &&
        !(statusCode === 400 || statusCode === 403 || statusCode === 404 || (statusCode >= 500 && statusCode <= 599))
      ) {
        // Ignore events that are NOT 400, 403, 404, or 500-599
        return null;
      }
      return event;
    },

    integrations: [
      Sentry.piniaIntegration(usePinia(), { attachPiniaState: false }),
      Sentry.httpClientIntegration({
        failedRequestStatusCodes: [400, 403, 404, [500, 599]],
      }),
      Sentry.feedbackIntegration({
        colorScheme: 'light',
        useSentryUser: {
          name: 'username',
          email: 'email',
        },
        autoInject: false,
      }),
    ],
    normalizeDepth: 5,

    // tracesSampleRate: 1.0,

    environment: environment,
    release: sentryRelease,

    debug: false,

    transportOptions: {
      headers: {
        'content-type': 'application/x-sentry-envelope',
      },
    },
  });
